/*
 * XP skin.css: pack's --xp-* palette + effect utilities. Import AFTER tailwindcss + theme.css.
 * xp- prefix avoids @utility collisions when multiple skins co-compile in one Tailwind build.
 */

/* Luna palette: pack's OWN --xp-* tokens (not theme.css contract — pack-owned, lives w/ consumers).
 * Mode-dependent, same light/dark scoping as theme.css.
 * Unlayered so class-string consumers (skin.config, adornments, tab recipe) resolve them. */
[data-skin="xp"] {
  --xp-bevel-light: oklch(1 0 0);
  --xp-bevel-dark: oklch(0.7307 0.0216 94.606);
  --xp-separator: oklch(0.7307 0.0216 94.606);
  --xp-field-border: oklch(0.6833 0.0533 246.812);
  --xp-control-border: oklch(0.3571 0.1109 253.22);
  --xp-control-top: oklch(1 0 0);
  --xp-control-bottom: oklch(0.9392 0.0081 98.883);
  --xp-frame: oklch(0.5021 0.2181 261.634);
  --xp-titlebar-top: oklch(0.5675 0.2209 259.619);
  --xp-titlebar-bottom: oklch(0.5139 0.2414 262.497);
  --xp-titlebar-edge: oklch(0.4166 0.2017 262.676);
  --xp-tab-face-top: oklch(1 0 0);
  --xp-tab-face-bottom: oklch(0.9318 0.0228 98.65);
  --xp-tab-accent: oklch(0.7182 0.1505 61.354);
  --xp-groupbox-border: oklch(0.8463 0.022 98.164);
  --xp-task-pane-top: oklch(0.9646 0.0166 271.243);
  --xp-task-pane-bottom: oklch(0.8693 0.0516 270.761);
  --xp-link: oklch(0.47 0.1754 260.787);
  --xp-bubble-user-top: oklch(0.9159 0.0302 260.711);
  --xp-bubble-user-bottom: oklch(0.8626 0.0449 259.947);
  --xp-scroll-track: oklch(0.9535 0.008 106.55);
  --xp-scroll-thumb-top: oklch(0.8922 0.0408 257.509);
  --xp-scroll-thumb-bottom: oklch(0.8366 0.059 254.828);
  --xp-scroll-thumb-border: oklch(0.6845 0.0601 245.565);
  --xp-skeleton: oklch(0.907 0.0215 101.011);
  /* Luna default-button (pale-blue) gradient + inner ring, and the red close-box gradient */
  --xp-solid-top: oklch(0.994 0 0);
  --xp-solid-bottom: oklch(0.9171 0.0329 256.763);
  --xp-solid-ring: oklch(0.7746 0.0723 256.434);
  --xp-close-top: oklch(0.6781 0.1528 37.514);
  --xp-close-bottom: oklch(0.5896 0.1829 24.717);
}

/* Dark — "Royale Noir" homage. Scoped like the light block (never a bare .dark subtree). */
:where(.dark) [data-skin="xp"],
.dark[data-skin="xp"] {
  --xp-bevel-light: oklch(0.3997 0.0135 256.758);
  --xp-bevel-dark: oklch(0.1809 0.0052 248.116);
  --xp-separator: oklch(0.3847 0.0136 256.762);
  --xp-field-border: oklch(0.4441 0.0229 248.341);
  --xp-control-border: oklch(0.2467 0.0705 262.092);
  --xp-control-top: oklch(0.3576 0.0124 252.965);
  --xp-control-bottom: oklch(0.2795 0.0085 255.574);
  --xp-frame: oklch(0.3929 0.1392 263.211);
  --xp-titlebar-top: oklch(0.4753 0.1587 263.3);
  --xp-titlebar-bottom: oklch(0.3929 0.1392 263.211);
  --xp-titlebar-edge: oklch(0.2959 0.0961 263.412);
  --xp-tab-face-top: oklch(0.3349 0.0104 253.978);
  --xp-tab-face-bottom: oklch(0.2795 0.0085 255.574);
  --xp-tab-accent: oklch(0.7002 0.1411 65.624);
  --xp-groupbox-border: oklch(0.3624 0.0117 258.367);
  --xp-task-pane-top: oklch(0.2831 0.0326 269.245);
  --xp-task-pane-bottom: oklch(0.2405 0.0261 268.121);
  --xp-link: oklch(0.7537 0.089 260.792);
  --xp-bubble-user-top: oklch(0.3489 0.051 262.958);
  --xp-bubble-user-bottom: oklch(0.3023 0.0446 264.304);
  --xp-scroll-track: oklch(0.2672 0.0086 255.58);
  --xp-scroll-thumb-top: oklch(0.4102 0.0449 259.658);
  --xp-scroll-thumb-bottom: oklch(0.3466 0.0387 260.466);
  --xp-scroll-thumb-border: oklch(0.5083 0.0442 255.724);
  --xp-skeleton: oklch(0.3122 0.0099 260.713);
  --xp-solid-top: oklch(0.369 0.0159 255.615);
  --xp-solid-bottom: oklch(0.3481 0.0515 261.732);
  --xp-solid-ring: oklch(0.492 0.081 260.654);
  --xp-close-top: oklch(0.5465 0.1437 30.284);
  --xp-close-bottom: oklch(0.4553 0.1345 27.22);
}

@layer components {
  /* Inherited skin typography; component text utilities stay authoritative. */
  [data-skin="xp"] body {
    font-family: var(--font-sans);
    font-size: 0.75rem;
  }

  [data-skin="xp"]
    :where(
      [data-control-ui="button"][data-slot="root"][data-control-family="button"],
      [data-control-ui="toggle"][data-slot="root"][data-control-family="button"]
    ) {
    --cui-button-radius: max(3px, var(--radius-control));
    --cui-button-gap: 0.25rem;
    --cui-button-foreground: var(--foreground);
    --cui-button-hover-bg: transparent;
    --cui-button-hover-foreground: var(--foreground);
    line-height: 1;
    --cui-button-press-bg: transparent;
    --cui-button-shadow: 0 0 transparent;
    --cui-button-active-bg: transparent;
    --cui-button-active-foreground: var(--foreground);
    --cui-button-active-hover-bg: transparent;
    /* Luna reads the raised bevel on hover and inverts it on press. */
    --cui-button-hover-shadow: inset 1px 1px 0 var(--xp-bevel-light), inset -1px -1px 0 var(--xp-bevel-dark);
    --cui-button-press-shadow: inset 1px 1px 0 var(--xp-bevel-dark), inset -1px -1px 0 var(--xp-bevel-light);
    border: 1px solid transparent;
  }

  @media (hover: hover) {
    [data-skin="xp"]
      :where(
        [data-control-ui="button"][data-slot="root"][data-control-family="button"]:hover,
        [data-control-ui="toggle"][data-slot="root"][data-control-family="button"]:hover
      ) {
      border-color: var(--xp-bevel-dark);
    }
  }

  [data-skin="xp"]
    :where(
      [data-control-ui="button"][data-slot="root"][data-variant="surface"][data-control-family="button"],
      [data-control-ui="toggle"][data-slot="root"][data-variant="surface"][data-control-family="button"]
    ) {
    --cui-button-press-scale: 1;
    --cui-button-shadow: inset 0 1px 0 var(--xp-bevel-light);
    --cui-button-active-shadow: inset 0 1px 0 var(--xp-bevel-light);
    --cui-button-hover-shadow: inset 0 0 0 1px var(--ring), inset 0 1px 0 var(--xp-bevel-light);
    --cui-button-press-shadow: inset 0 1px 0 var(--xp-bevel-light);
    --cui-button-bg-image: linear-gradient(to bottom, var(--xp-control-top), var(--xp-control-bottom));
    border-color: var(--xp-control-border);
  }

  @media (hover: hover) {
    [data-skin="xp"]
      :where(
        [data-control-ui="button"][data-slot="root"][data-variant="surface"][data-control-family="button"]:hover,
        [data-control-ui="toggle"][data-slot="root"][data-variant="surface"][data-control-family="button"]:hover
      ) {
      border-color: var(--xp-control-border);
    }
  }

  [data-skin="xp"]
    :where(
      [data-control-ui="button"][data-slot="root"][data-variant="surface"][data-control-family="button"]:active,
      [data-control-ui="toggle"][data-slot="root"][data-variant="surface"][data-control-family="button"]:active
    ) {
    --cui-button-bg-image: linear-gradient(to bottom, var(--xp-control-bottom), var(--xp-control-top));
  }

  [data-skin="xp"]
    :where(
      [data-control-ui="button"][data-slot="root"][data-variant="solid"][data-control-family="button"],
      [data-control-ui="toggle"][data-slot="root"][data-variant="solid"][data-control-family="button"]
    ) {
    --cui-button-press-scale: 1;
    --cui-button-shadow: inset 0 0 0 1px var(--xp-solid-ring), inset 0 1px 0 var(--xp-bevel-light);
    --cui-button-bg-image: linear-gradient(to bottom, var(--xp-solid-top), var(--xp-solid-bottom));
    border-color: var(--xp-control-border);
    font-weight: 700;
  }

  /* classic XP tab strip: baseline recipe keeps geometry/states; knobs re-value component-local vars.
     un-tokenizable Luna reading stays as rules: raised gradient boxes on the Luna desktop gray; active tab white,
     1px taller, cuts baseline, wears orange top stripe (tabs-indicator slides via Base UI --active-tab-* vars).
     None of it reaches the browser variant: its chrome (flare, outline, notch) comes from the recipe, and a real
     border-bottom can never be notched — the indicator stops at the padding box. */
  [data-skin="xp"] :where([data-slot="list"][data-control-family="tabs"]:not([data-variant="browser"])) {
    --_tabs-list-h: calc(var(--_tabs-trigger-h) + 3px); /* squares the strip; the tab/indicator keep their own 3px tops */
    align-items: flex-end;
    /* gap stays a real declaration: the line variant resets it to 0 and the Luna strip must hold either way. */
    gap: 2px;
    border-bottom: 1px solid var(--border);
  }
  [data-skin="xp"] :where([data-slot="root"][data-control-family="tabs"]) {
    --cui-tabs-trigger-radius: 3px;
    --cui-tabs-list-padding: 0px;
    --cui-tabs-list-background: transparent;
    --cui-tabs-foreground: var(--foreground);
    --cui-tabs-active-foreground: var(--foreground);
    --cui-tabs-indicator-background: var(--xp-tab-accent);
    --cui-tabs-indicator-shadow: none;
  }

  /* The browser variant drops the accent stripe for the page surface it continues. */
  [data-skin="xp"] :where([data-slot="list"][data-variant="browser"][data-control-family="tabs"]) {
    --cui-tabs-indicator-background: var(--background);
  }

  [data-skin="xp"]
    :where([data-slot="list"][data-control-family="tabs"]:not([data-variant="browser"]) [data-slot="tab"][data-control-family="tabs"]) {
    /* height/cursor restated (baseline values) so the single-tab reset keeps the full Luna box */
    height: var(--_tabs-trigger-h);
    cursor: pointer;
    border: 1px solid var(--border);
    border-bottom: none;
    /* the tab radius stays the knob's; only the bottom is squared off, where the tab meets the baseline. */
    border-end-start-radius: 0;
    border-end-end-radius: 0;
    background: linear-gradient(180deg, var(--xp-tab-face-top) 0%, var(--xp-tab-face-bottom) 100%);
    padding-inline: 0.75rem;
    font-weight: 400;
    transition: color var(--duration-fast) var(--ease-standard);
  }

  [data-skin="xp"]
    :where(
      [data-slot="list"][data-control-family="tabs"]:not([data-variant="browser"])
        [data-slot="tab"][aria-selected="true"][data-control-family="tabs"]
    ),
  [data-skin="xp"]
    :where(
      [data-slot="list"][data-control-family="tabs"]:not([data-variant="browser"])
        [data-slot="tab"][data-active][data-control-family="tabs"]
    ) {
    height: calc(var(--_tabs-trigger-h) + 2px);
    margin-bottom: -1px;
    background: var(--background);
  }

  [data-skin="xp"]
    :where(
      [data-slot="list"][data-control-family="tabs"]:not([data-variant="browser"]) [data-slot="indicator"][data-control-family="tabs"]
    ) {
    top: 1px;
    bottom: auto;
    z-index: 2;
    height: 3px;
    transform: translateX(var(--active-tab-left));
    border-end-start-radius: 0; /* also caps the line variant's pill indicator, as before */
    border-end-end-radius: 0;
  }
}

/* xp-bevel-up: raised toolbar edge (light top-left, dark bottom-right); buttons flat until hover pops this. */
@utility xp-bevel-up {
  box-shadow:
    inset 1px 1px 0 var(--xp-bevel-light),
    inset -1px -1px 0 var(--xp-bevel-dark);
}

/* xp-bevel-down — the pressed reading: the bevel inverts so the control sinks into the surface. */
@utility xp-bevel-down {
  box-shadow:
    inset 1px 1px 0 var(--xp-bevel-dark),
    inset -1px -1px 0 var(--xp-bevel-light);
}

/* xp-gloss: bright wash over top half of surface; painted on ::before, content should sit above z-0. */
@utility xp-gloss {
  position: relative;

  &::before {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0 0 45% 0;
    border-radius: inherit;
    background: linear-gradient(180deg, oklch(1 0 0 / 0.55) 0%, oklch(1 0 0 / 0.08) 100%);
  }
}

/* xp-pinstripes — the faint vertical Luna watermark texture for wide surfaces. */
@utility xp-pinstripes {
  background-image: repeating-linear-gradient(90deg, oklch(from var(--foreground) l c h / 0.03) 0 1px, transparent 1px 4px);
}

/* "generating" treatment = library progress-sweep effect (effects.css); defaults already match XP sweep, pack re-values nothing. */

/* xp-groupbox: classic dialog groupbox groove; box needs position:relative + padding, float label over top edge yourself. */
@utility xp-groupbox {
  border-radius: 3px;
  border: 1px solid var(--xp-groupbox-border);
  box-shadow: inset 1px 1px 0 var(--xp-bevel-light);
}

@layer components {
  [data-skin="xp"]
    :where([data-control-family="popup"][data-popup-part="surface"], [data-control-family="popup"][data-popup-part="list-surface"]) {
    --cui-popup-radius: 0px;
    --cui-popup-background: var(--popover);
    --cui-popup-foreground: var(--foreground);
    --cui-popup-border-color: var(--xp-field-border);
    --cui-popup-border-width: 1px;
    --cui-popup-shadow: 3px 3px 4px oklch(0 0 0 / 0.35);
    --cui-popup-backdrop-filter: none;
  }

  [data-skin="xp"] :where([data-popup-part="list-surface"]) {
    padding: 0.125rem;
  }

  [data-skin="xp"] :where([data-popup-part="item"]) {
    min-height: 1.5rem;
    padding: 0.125rem 1.25rem;
    font-size: 0.75rem;
  }

  [data-skin="xp"] :where([data-popup-part="item"][data-highlighted]) {
    color: var(--primary-foreground);
  }

  [data-skin="xp"] :where([data-popup-part="label"]) {
    font-size: 0.6875rem;
    letter-spacing: normal;
    text-transform: none;
  }

  [data-skin="xp"]
    :where(
      [data-control-family="popup"][data-popup-part="surface"],
      [data-control-family="popup"][data-popup-part="list-surface"],
      [data-control-family="popup"][data-popup-part="bar"]
    ) {
    --cui-popup-item-radius: 0px;
    --cui-popup-item-highlight-background: var(--primary);
    --cui-popup-item-highlight-foreground: var(--primary-foreground);
    --cui-popup-item-highlight-muted-foreground: var(--primary-foreground);
    --cui-popup-item-disabled-opacity: 0.4;
    --cui-popup-separator-color: var(--xp-separator);
  }

  [data-skin="xp"] :where([data-popup-part="separator"]) {
    margin-inline: 0.25rem;
  }

  [data-skin="xp"] :where([data-popup-part="shortcut"]) {
    font-size: 0.6875rem;
  }

  [data-skin="xp"]
    :where(
      [data-control-ui="select"][data-slot="trigger"][data-control-family="button"],
      [data-control-ui="dropdown-menu"][data-slot="trigger"][data-control-family="button"]
    ) {
    --cui-button-radius: max(3px, var(--radius-control));
    --cui-button-bg: var(--xp-control-bottom);
    --cui-button-foreground: var(--foreground);
    --cui-button-hover-bg: var(--xp-control-top);
    --cui-button-hover-foreground: var(--foreground);
    --cui-button-press-bg: var(--xp-control-bottom);
    --cui-button-press-scale: 1;
    --cui-button-shadow: inset 0 1px 0 var(--xp-bevel-light);
    border: 1px solid var(--xp-control-border);
    background-image: linear-gradient(to bottom, var(--xp-control-top), var(--xp-control-bottom));
  }

  [data-skin="xp"]
    :where(
      [data-control-ui="select"][data-slot="trigger"][data-control-family="button"],
      [data-control-ui="dropdown-menu"][data-slot="trigger"][data-control-family="button"]
    ):active {
    background-image: linear-gradient(to bottom, var(--xp-control-bottom), var(--xp-control-top));
  }

  [data-skin="xp"] :where([data-control-ui="select"][data-slot="icon"][data-control-family="popup"]) {
    rotate: 0deg;
    color: var(--xp-control-border);
  }
  [data-skin="xp"] :where([data-control-ui="dialog"][data-popup-part="surface"][data-control-family="popup"]) {
    --cui-popup-radius: 5px 5px 0 0;
    --cui-popup-background: var(--background);
    --cui-popup-border-color: var(--xp-frame);
    --cui-popup-border-width: 3px;
    --cui-popup-shadow: 3px 3px 8px oklch(0 0 0 / 0.35);
    --cui-popup-backdrop-filter: none;
  }

  [data-skin="xp"] :where([data-control-ui="dialog"][data-slot="header"][data-control-family="popup"]) {
    padding: 0.5rem 0.75rem 0;
  }

  [data-skin="xp"] :where([data-control-ui="dialog"][data-slot="title"][data-control-family="popup"]) {
    font-size: 0.8125rem;
    font-weight: 700;
  }

  [data-skin="xp"] :where([data-control-ui="dialog"][data-slot="description"][data-control-family="popup"]) {
    color: var(--muted-foreground);
    font-size: 0.75rem;
  }

  [data-skin="xp"] :where([data-control-family="button"][data-popup-part="close"]) {
    --cui-button-radius: 3px;
    --cui-button-bg: var(--xp-close-bottom);
    --cui-button-foreground: white;
    --cui-button-hover-bg: var(--xp-close-top);
    --cui-button-hover-foreground: white;
    --cui-button-press-bg: var(--xp-close-bottom);
    --cui-button-shadow: inset 0 1px 0 oklch(1 0 0 / 0.45);
    border: 1px solid oklch(1 0 0 / 0.7);
    background-image: linear-gradient(to bottom, var(--xp-close-top), var(--xp-close-bottom));
  }
}

@layer components {
  [data-skin="xp"] :where([data-control-family="field"][data-control="true"]) {
    --cui-field-radius: var(--radius-control);
    --cui-field-background: var(--background);
    --cui-field-foreground: var(--foreground);
    --cui-field-border-color: var(--xp-field-border);
    --cui-field-border-width: 1px;
    --cui-field-shadow: inset 1px 1px 0 var(--xp-bevel-dark);
    --cui-field-focus-border-color: var(--primary);
  }
}
@layer components {
  [data-skin="xp"] :where([data-slot="root"][data-control-family="sidebar"]) {
    --cui-sidebar-inner-background: var(--xp-task-pane-top);
    --cui-sidebar-inner-background-image: linear-gradient(to bottom, var(--xp-task-pane-top), var(--xp-task-pane-bottom));
    --cui-sidebar-inner-border-color: var(--xp-field-border);
    --cui-sidebar-inner-border-width: 1px;
    --cui-sidebar-inner-radius: 0px;
    --cui-sidebar-inner-shadow: none;
    --cui-sidebar-menu-button-radius: 0px;
    --cui-sidebar-menu-button-foreground: var(--xp-link);
    --cui-sidebar-menu-button-hover-background: oklch(from var(--primary) l c h / 0.1);
    --cui-sidebar-menu-button-active-background: var(--card);
    --cui-sidebar-menu-button-active-foreground: var(--xp-link);
    --cui-sidebar-group-label-foreground: var(--xp-link);
  }

  [data-skin="xp"] :where([data-slot="group-label"][data-control-family="sidebar"]) {
    text-transform: none;
  }

  [data-skin="xp"] :where([data-control-ui="slider"][data-slot="root"][data-control-family="range"]) {
    --cui-range-track-radius: var(--radius-control);
    --cui-range-track-background: var(--xp-scroll-track);
    --cui-range-indicator-radius: var(--radius-control);
    --cui-range-indicator-background: var(--primary);
    --cui-range-thumb-radius: var(--radius-control);
    --cui-range-thumb-background: linear-gradient(to bottom, var(--xp-control-top), var(--xp-control-bottom));
    --cui-range-thumb-border-color: var(--xp-control-border);
    --cui-range-thumb-shadow: inset 0 1px 0 var(--xp-bevel-light);
  }

  [data-skin="xp"] :where([data-slot="scrollbar"][data-control-family="scroll-area"]) {
    border-radius: 0;
    background: var(--xp-scroll-track);
    box-shadow: inset 0 0 0 1px oklch(from var(--xp-separator) l c h / 0.55);
  }

  [data-skin="xp"] :where([data-slot="root"][data-control-family="scroll-area"]) {
    --cui-scroll-area-thumb-radius: 0px;
    --cui-scroll-area-thumb-background:
      repeating-linear-gradient(180deg, oklch(from var(--xp-bevel-light) l c h / 0.9) 0 1px, transparent 1px 3px),
      linear-gradient(90deg, var(--xp-scroll-thumb-top) 0%, var(--xp-scroll-thumb-bottom) 100%);
  }

  [data-skin="xp"] :where([data-slot="thumb"][data-control-family="scroll-area"]) {
    border: 1px solid var(--xp-scroll-thumb-border);
    background-position:
      center,
      0 0;
    background-size:
      6px 10px,
      100% 100%;
    background-repeat: no-repeat;
  }

  [data-skin="xp"] :where([data-control-ui="chat-composer"][data-slot="root"][data-control-family="chat-composer"]) {
    --cui-chat-composer-shell-background: var(--background);
    --cui-chat-composer-shell-border-color: var(--xp-field-border);
    --cui-chat-composer-shell-radius: var(--radius-control);
    --cui-chat-composer-shell-shadow: inset 1px 1px 0 var(--xp-bevel-dark);
    --cui-chat-composer-input-foreground: var(--foreground);
  }

  [data-skin="xp"] :where([data-slot="root"][data-control-family="markdown-block"]) {
    --cui-markdown-block-radius: 0px;
    --cui-markdown-block-border-color: var(--xp-groupbox-border);
    --cui-markdown-block-header-border-color: var(--xp-groupbox-border);
  }

  [data-skin="xp"] :where([data-slot="header"][data-control-family="markdown-block"]) {
    background-color: var(--secondary);
  }

  [data-skin="xp"] :where([data-slot="root"][data-control-family="thread-rail"]) {
    --cui-thread-rail-item-radius: 0px;
    --cui-thread-rail-line-radius: 0px;
  }

  [data-skin="xp"] :where([data-control-ui="chat-layout"][data-slot="root"][data-control-family="chat-layout"]) {
    --cui-chat-layout-radius: 8px;
    --cui-chat-layout-border-color: var(--xp-frame);
    --cui-chat-layout-shadow: 3px 3px 8px oklch(0 0 0 / 0.35);
    border-width: 3px;
    border-end-start-radius: 0;
    border-end-end-radius: 0;
  }

  /* The Luna scrollbar rides the native bars, so it lands on whatever part owns the overflow. */
  [data-skin="xp"]
  :where(
    [data-slot="root"][data-control-family="scroll-area"],
    [data-slot="root"][data-control-family="markdown-block"],
    [data-control-ui="chat-thread"][data-slot="root"][data-control-family="chat-layout"]
  ) {
    scrollbar-color: var(--xp-scroll-thumb-bottom) var(--xp-scroll-track);

    &::-webkit-scrollbar {
      width: 14px;
      height: 14px;
    }

    &::-webkit-scrollbar-track {
      background: var(--xp-scroll-track);
      box-shadow: inset 0 0 0 1px oklch(from var(--xp-separator) l c h / 0.55);
    }

    &::-webkit-scrollbar-thumb {
      border: 1px solid var(--xp-scroll-thumb-border);
      background: linear-gradient(90deg, var(--xp-scroll-thumb-top) 0%, var(--xp-scroll-thumb-bottom) 100%);
    }

    &::-webkit-scrollbar-corner {
      background: var(--xp-scroll-track);
    }
  }
}

@layer components {
  [data-skin="xp"] :where([data-slot="root"][data-role="user"][data-control-family="chat-message"]) {
    --cui-chat-message-radius: 3px;
    --cui-chat-message-corner-radius: 3px;
    --cui-chat-message-background: var(--background);
    --cui-chat-message-background-image: linear-gradient(to bottom, var(--xp-bubble-user-top), var(--xp-bubble-user-bottom));
    --cui-chat-message-border-color: var(--xp-field-border);
    --cui-chat-message-border-width: 1px;
    --cui-chat-message-shadow: inset 0 1px 0 var(--xp-bevel-light);
    --cui-chat-message-foreground: var(--foreground);
  }

  [data-skin="xp"] :where([data-slot="content"][data-streaming][data-control-family="chat-message"]) {
    @apply progress-sweep;
  }

  [data-skin="xp"] :where([data-slot="root"][data-control-family="skeleton"]) {
    --cui-skeleton-background: var(--xp-skeleton);
    background-image: none;
  }
}

/* Windows XP "Luna". */

[data-skin="xp"][data-skin] {
  /* typography — Tahoma first: the Luna system face */
  --font-sans: Tahoma, "Segoe UI", "Trebuchet MS", Verdana, ui-sans-serif, sans-serif;
  --font-mono: "Lucida Console", Consolas, monospace;

  /* type scale — Tahoma reads at the Luna 13px body rung; the other explicit rungs keep a compact hierarchy */
  --text-body: 0.8125rem; /* 13px */

  /* color — shadcn base names, full colors */
  --background: oklch(1 0 0);
  --foreground: oklch(0.2178 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.2178 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.2178 0 0);
  --primary: oklch(0.5354 0.1543 259.46); /* XP selection blue */
  --primary-foreground: oklch(1 0 0);
  --muted: oklch(0.9501 0.0174 99.605);
  --muted-foreground: oklch(0.47 0.0245 98.401);
  --secondary: oklch(0.9318 0.0228 98.65);
  --secondary-foreground: oklch(0.2178 0 0);
  --accent: oklch(0.5354 0.1543 259.46); /* XP highlight = solid selection blue with white text */
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.577 0.1823 25.932);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.6817 0.0116 204.079 / var(--ring-opacity));
  --input: oklch(0.6833 0.0533 246.812); /* classic field border */
  --ring: oklch(0.8118 0.1544 77.609); /* XP orange focus glow */
  --focus-ring: var(--foreground);
  --focus-ring-style: dotted;
  --focus-ring-width: 1px;
  --focus-ring-offset: -4px;

  /* page canvas — the XP dialog beige every panel sits on */
  --canvas: oklch(0.9318 0.0228 98.65);

  /* floating surfaces are solid in XP — no glass */
  --popover-opacity: 1;
  --backdrop-blur-popover: 0px;

  /* modal overlay — plain dim, no blur */
  --overlay-opacity: 0.3;
  --backdrop-blur-overlay: 0px;

  /* hard scroll edges: the square DA never fades clipped content */
  --scroll-fade-size: 0rem;

  /* elevation — low size, hard offset shadows */
  --shadow-color: oklch(0 0 0);
  --shadow-size: 0.4;
  --shadow-opacity: 1;

  /* THE one radius knob: 0 squares the whole DA. Controls consume --radius-control (0 here → square);
     buttons floor it at Luna's 3px via max(3px, --radius-control) in skin.config.tsx. So the corner is
     token-driven — raising --radius (theme editor) rounds XP controls instead of leaving them inert. */
  --radius: 0rem;
  --radius-control: calc(var(--radius) * 2);

  /* corner shape stays round — square boxes have no corner arc to reshape */

  /* floating-list geometry: same derivations as Refined; --radius 0 collapses them to square rows/container = XP menu. */
  --popover-padding: 2px;
  --radius-popup-item: calc(var(--radius-control) * 0.6);

  /* content density — XP runs tighter than the Refined skin */
  --padding-x: 0.75rem;
  --padding-y: 0.5rem;

  /* control size scale — ONE base height; the ramp derives from it */
  --control-h: 2rem;
  /* round() to whole px so no derived step lands on a subpixel height (mirrors Refined). */

  /* motion — XP does not ease: linear curves, near-instant tempos */
  --ease-standard: linear;
  --ease-emphasized: linear;
  --duration-fast: 40ms;
  --duration-base: 60ms;
  --duration-slow: 80ms;
  --text-label: 0.75rem;
  --radius-field: calc(var(--radius) * 2.2);
  --radius-panel: calc(var(--radius) * 2.6);
  --radius-scene: calc(var(--radius) * 2.8);
}

/* Dark tokens — "Royale Noir" homage, re-asserted on/under a dark XP root so the light values never win by proximity. */
:where(.dark) [data-skin="xp"][data-skin],
.dark[data-skin="xp"][data-skin] {
  --background: oklch(0.2459 0.0072 248.122);
  --foreground: oklch(0.919 0.0071 88.645);
  --card: oklch(0.2795 0.0085 255.574);
  --card-foreground: oklch(0.919 0.0071 88.645);
  --popover: oklch(0.2795 0.0085 255.574);
  --popover-foreground: oklch(0.919 0.0071 88.645);
  --primary: oklch(0.5512 0.1425 260.917);
  --primary-foreground: oklch(1 0 0);
  --muted: oklch(0.2958 0.0084 255.567);
  --muted-foreground: oklch(0.7028 0.0111 247.986);
  --secondary: oklch(0.2958 0.0084 255.567);
  --secondary-foreground: oklch(0.919 0.0071 88.645);
  --accent: oklch(0.5016 0.1504 261.426);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.574 0.1623 27.404);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.3847 0.0136 256.762 / var(--ring-opacity));
  --input: oklch(0.4441 0.0229 248.341);
  --ring: oklch(0.7319 0.1299 74.539);
  --canvas: oklch(0.1763 0.0052 248.125);
  --shadow-color: oklch(0 0 0);
}

/* XP collapses motion UNCONDITIONALLY (Luna tempo IS "reduced"; skin.config matches with motion:"reduced" flag).
   always-on, de-gated from prefers-reduced-motion, so standalone installs snap without the docs theme editor.
   declared after token block above on purpose, to override the near-instant Luna values there. */
[data-skin="xp"][data-skin] {
  --duration-fast: 0ms;
  --duration-base: 0ms;
  --duration-slow: 0ms;
}
